using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=key;", "Shop");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 changed the default discriminator property
        // from "Discriminator" to "$type". Existing documents still store
        // "Discriminator", so we must pin the old name to avoid data mismatch.
        modelBuilder.Entity<Product>()
            .HasDiscriminatorInJsonProperty("Discriminator");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

class CosmosQueryService
{
    // Breaking change: EF Core 9 Cosmos provider removed synchronous query
    // support. All queries must use async methods (ToListAsync, FirstAsync, etc.).
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products.ToListAsync();
    }
}

